export function tr(fr, vars) {
  let s = LANG === "en" && EN[fr] !== undefined ? EN[fr] : fr;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return s;
}
